CREATE TRIGGER research_versions_status BEFORE UPDATE OF status ON research_versions WHEN NEW.status<>OLD.status AND NOT ((OLD.status='DRAFT' AND NEW.status='CANDIDATE') OR (OLD.status='CANDIDATE' AND NEW.status IN ('APPROVED','INVALIDATED')) OR (OLD.status='APPROVED' AND NEW.status IN ('SUPERSEDED','INVALIDATED'))) BEGIN SELECT RAISE(ABORT,'VERSION_TRANSITION_INVALID'); END;
